#include "zebra_puzzle.h"

#include <array>
#include <string_view>

namespace zebra_puzzle {

namespace {

constexpr int kHouses = 5;

// Attribute categories, each a permutation of 0..4 assigned to houses 0..4.
enum { kNationality, kColor, kPet, kDrink, kHobby, kCategories };

// Values within each category.
constexpr std::string_view kNationalities[] = {
    "Englishman", "Spaniard", "Ukrainian", "Japanese", "Norwegian"};
constexpr std::string_view kColors[] = {"Red", "Green", "Ivory", "Yellow", "Blue"};
constexpr std::string_view kPets[] = {"Dog", "Snail", "Fox", "Horse", "Zebra"};
constexpr std::string_view kDrinks[] = {"Coffee", "Tea", "Milk", "OrangeJuice", "Water"};
constexpr std::string_view kHobbies[] = {"Dancing", "Reading", "Painter", "Football", "Chess"};

const std::string_view kCategoryNames[kCategories] = {
    kNationalities, kColors, kPets, kDrinks, kHobbies};

// house[category][house] = value index, -1 means unassigned.
struct Assignment {
    int house[kCategories][kHouses];
};

bool isConsistent(const Assignment& a) {
    // 2. Englishman lives in the red house.
    for (int h = 0; h < kHouses; ++h) {
        if (a[kNationality][h] == 0 && a[kColor][h] != 0) return false;
        if (a[kColor][h] == 0 && a[kNationality][h] != 0) return false;
    }
    // 3. Spaniard owns the dog.
    for (int h = 0; h < kHouses; ++h) {
        if (a[kNationality][h] == 1 && a[kPet][h] != 1) return false;
        if (a[kPet][h] == 1 && a[kNationality][h] != 1) return false;
    }
    // 4. Green house drinks coffee.
    for (int h = 0; h < kHouses; ++h) {
        if (a[kColor][h] == 1 && a[kDrink][h] != 0) return false;
        if (a[kDrink][h] == 0 && a[kColor][h] != 1) return false;
    }
    // 5. Ukrainian drinks tea.
    for (int h = 0; h < kHouses; ++h) {
        if (a[kNationality][h] == 2 && a[kDrink][h] != 1) return false;
        if (a[kDrink][h] == 1 && a[kNationality][h] != 2) return false;
    }
    // 6. Green house is immediately to the right of the ivory house.
    for (int h = 0; h < kHouses; ++h) {
        if (a[kColor][h] == 1) {
            if (h == 0) return false;
            if (a[kColor][h - 1] != 2) return false;
        }
        if (a[kColor][h] == 2) {
            if (h == kHouses - 1) return false;
            if (a[kColor][h + 1] != 1) return false;
        }
    }
    // 7. Snail owner likes to go dancing.
    for (int h = 0; h < kHouses; ++h) {
        if (a[kPet][h] == 2 && a[kHobby][h] != 0) return false;
        if (a[kHobby][h] == 0 && a[kPet][h] != 2) return false;
    }
    // 8. Yellow house is a painter.
    for (int h = 0; h < kHouses; ++h) {
        if (a[kColor][h] == 3 && a[kHobby][h] != 2) return false;
        if (a[kHobby][h] == 2 && a[kColor][h] != 3) return false;
    }
    // 9. Middle house drinks milk.
    if (a[kDrink][2] != 2) return false;
    // 10. Norwegian lives in the first house.
    if (a[kNationality][0] != 4) return false;
    // 11. Reading lives next to the fox.
    for (int h = 0; h < kHouses; ++h) {
        if (a[kHobby][h] == 1) {
            bool nearFox = false;
            for (int n = h - 1; n <= h + 1; ++n) {
                if (n >= 0 && n < kHouses && a[kPet][n] == 3) nearFox = true;
            }
            if (!nearFox) return false;
        }
        if (a[kPet][h] == 3) {
            bool nearReading = false;
            for (int n = h - 1; n <= h + 1; ++n) {
                if (n >= 0 && n < kHouses && a[kHobby][n] == 1) nearReading = true;
            }
            if (!nearReading) return false;
        }
    }
    // 12. Painter's house is next to the horse.
    for (int h = 0; h < kHouses; ++h) {
        if (a[kHobby][h] == 2) {
            bool nearHorse = false;
            for (int n = h - 1; n <= h + 1; ++n) {
                if (n >= 0 && n < kHouses && a[kPet][n] == 4) nearHorse = true;
            }
            if (!nearHorse) return false;
        }
        if (a[kPet][h] == 4) {
            bool nearPainter = false;
            for (int n = h - 1; n <= h + 1; ++n) {
                if (n >= 0 && n < kHouses && a[kHobby][n] == 2) nearPainter = true;
            }
            if (!nearPainter) return false;
        }
    }
    // 13. Football player drinks orange juice.
    for (int h = 0; h < kHouses; ++h) {
        if (a[kHobby][h] == 3 && a[kDrink][h] != 3) return false;
        if (a[kDrink][h] == 3 && a[kHobby][h] != 3) return false;
    }
    // 14. Japanese plays chess.
    for (int h = 0; h < kHouses; ++h) {
        if (a[kNationality][h] == 3 && a[kHobby][h] != 4) return false;
        if (a[kHobby][h] == 4 && a[kNationality][h] != 3) return false;
    }
    // 15. Norwegian lives next to the blue house.
    for (int h = 0; h < kHouses; ++h) {
        if (a[kColor][h] == 4) {
            if (h != 1) return false;  // Norwegian is in house 0, so blue must be house 1.
        }
    }
    return true;
}

bool solve(Assignment& a, int category) {
    if (category == kCategories) {
        return isConsistent(a);
    }
    for (int value = 0; value < kHouses; ++value) {
        for (int house = 0; house < kHouses; ++house) {
            if (a[category][house] != -1) continue;
            bool valueTaken = false;
            for (int h = 0; h < kHouses; ++h) {
                if (a[category][h] == value) valueTaken = true;
            }
            if (valueTaken) continue;
            a[category][house] = value;
            if (isConsistent(a) && solve(a, category + 1)) return true;
            a[category][house] = -1;
        }
    }
    return false;
}

}  // namespace

Solution solve() {
    Assignment a{};
    for (int c = 0; c < kCategories; ++c) {
        for (int h = 0; h < kHouses; ++h) {
            a.house[c][h] = -1;
        }
    }
    bool found = solve(a, 0);
    Solution result;
    if (!found) {
        result.drinksWater = "Unknown";
        result.ownsZebra = "Unknown";
        return result;
    }
    for (int h = 0; h < kHouses; ++h) {
        if (a.house[kDrink][h] == 4) {
            result.drinksWater = std::string(kCategoryNames[kNationality][a.house[kNationality][h]]);
        }
        if (a.house[kPet][h] == 4) {
            result.ownsZebra = std::string(kCategoryNames[kNationality][a.house[kNationality][h]]);
        }
    }
    return result;
}

}  // namespace zebra_puzzle

