#include <cstdio>
#include <string>
#include <vector>

int main() {
    // Brute force: assign each of 5 categories a permutation of 0..4.
    // Categories: 0 nationality, 1 color, 2 pet, 3 drink, 4 hobby.
    // Values:
    // nat: 0 Englishman,1 Spaniard,2 Ukrainian,3 Japanese,4 Norwegian
    // col: 0 Red,1 Green,2 Ivory,3 Yellow,4 Blue
    // pet: 0 Dog,1 Snail,2 Fox,3 Horse,4 Zebra
    // drk: 0 Coffee,1 Tea,2 Milk,3 OrangeJuice,4 Water
    // hob: 0 Dancing,1 Reading,2 Painter,3 Football,4 Chess

    int a[5][5];
    long long count = 0;
    for (int c0 = 0; c0 < 120; ++c0) {}
    // iterate all 5! permutations per category via nested loops over permutations
    auto perms = [](auto&& self, int n, std::vector<int>& p, int k, auto cb) {
        if (k == n) { cb(p); return; }
        for (int v = 0; v < n; ++v) {
            bool used = false;
            for (int i = 0; i < k; ++i) if (p[i] == v) used = true;
            if (used) continue;
            p[k] = v;
            self(self, n, p, k + 1, cb);
        }
    };
    std::vector<int> p(5);
    perms(perms, 5, p, 0, [&](const std::vector<int>& nat) {
        perms(perms, 5, p, 0, [&](const std::vector<int>& col) {
            perms(perms, 5, p, 0, [&](const std::vector<int>& pet) {
                perms(perms, 5, p, 0, [&](const std::vector<int>& drk) {
                    perms(perms, 5, p, 0, [&](const std::vector<int>& hob) {
                        for (int h = 0; h < 5; ++h) {
                            a[0][h] = nat[h]; a[1][h] = col[h]; a[2][h] = pet[h];
                            a[3][h] = drk[h]; a[4][h] = hob[h];
                        }
                        bool ok = true;
                        for (int h = 0; h < 5; ++h) {
                            if (a[0][h] == 0 && a[1][h] != 0) ok = false; // 2
                            if (a[1][h] == 0 && a[0][h] != 0) ok = false;
                            if (a[0][h] == 1 && a[2][h] != 1) ok = false; // 3
                            if (a[2][h] == 1 && a[0][h] != 1) ok = false;
                            if (a[1][h] == 1 && a[3][h] != 0) ok = false; // 4
                            if (a[3][h] == 0 && a[1][h] != 1) ok = false;
                            if (a[0][h] == 2 && a[3][h] != 1) ok = false; // 5
                            if (a[3][h] == 1 && a[0][h] != 2) ok = false;
                            if (a[1][h] == 2 && a[4][h] != 0) ok = false; // 7
                            if (a[4][h] == 0 && a[2][h] != 2) ok = false;
                            if (a[1][h] == 3 && a[4][h] != 2) ok = false; // 8
                            if (a[4][h] == 2 && a[1][h] != 3) ok = false;
                            if (a[4][h] == 3 && a[3][h] != 3) ok = false; // 13
                            if (a[3][h] == 3 && a[4][h] != 3) ok = false;
                            if (a[0][h] == 3 && a[4][h] != 4) ok = false; // 14
                            if (a[4][h] == 4 && a[0][h] != 3) ok = false;
                        }
                        // 6 green right of ivory
                        for (int h = 0; h < 5; ++h) {
                            if (a[1][h] == 1) { if (h == 0 || a[1][h-1] != 2) ok = false; }
                            if (a[1][h] == 2) { if (h == 4 || a[1][h+1] != 1) ok = false; }
                        }
                        if (a[3][2] != 2) ok = false; // 9
                        if (a[0][0] != 4) ok = false; // 10
                        // 11 reading next to fox
                        for (int h = 0; h < 5; ++h) {
                            if (a[4][h] == 1) {
                                bool f = false;
                                for (int n = h-1; n <= h+1; ++n) if (n>=0&&n<5&&a[2][n]==2) f = true;
                                if (!f) ok = false;
                            }
                            if (a[2][h] == 2) {
                                bool f = false;
                                for (int n = h-1; n <= h+1; ++n) if (n>=0&&n<5&&a[4][n]==1) f = true;
                                if (!f) ok = false;
                            }
                        }
                        // 12 painter next to horse
                        for (int h = 0; h < 5; ++h) {
                            if (a[4][h] == 2) {
                                bool f = false;
                                for (int n = h-1; n <= h+1; ++n) if (n>=0&&n<5&&a[2][n]==3) f = true;
                                if (!f) ok = false;
                            }
                            if (a[2][h] == 3) {
                                bool f = false;
                                for (int n = h-1; n <= h+1; ++n) if (n>=0&&n<5&&a[4][n]==2) f = true;
                                if (!f) ok = false;
                            }
                        }
                        // 15 norwegian next to blue
                        for (int h = 0; h < 5; ++h) if (a[1][h] == 4 && h != 1) ok = false;

                        if (ok) {
                            count++;
                            printf("SOLUTION %lld:\n", count);
                            const char* natn[]={"Englishman","Spaniard","Ukrainian","Japanese","Norwegian"};
                            const char* coln[]={"Red","Green","Ivory","Yellow","Blue"};
                            const char* petn[]={"Dog","Snail","Fox","Horse","Zebra"};
                            const char* drkn[]={"Coffee","Tea","Milk","OrangeJuice","Water"};
                            const char* hobn[]={"Dancing","Reading","Painter","Football","Chess"};
                            for (int h = 0; h < 5; ++h)
                                printf("  H%d: %s %s %s %s %s\n", h+1, natn[a[0][h]], coln[a[1][h]], petn[a[2][h]], drkn[a[3][h]], hobn[a[4][h]]);
                        }
                    });
                });
            });
        });
    });
    printf("total solutions: %lld\n", count);
    return 0;
}

#include <cstdio>
#include <vector>

static void perms(int n, std::vector<int>& p, int k, const std::function<void(const std::vector<int>&)>& cb) {
    if (k == n) { cb(p); return; }
    for (int v = 0; v < n; ++v) {
        bool used = false;
        for (int i = 0; i < k; ++i) if (p[i] == v) used = true;
        if (used) continue;
        p[k] = v;
        perms(n, p, k + 1, cb);
    }
}

