                            if (a[4][h]==3 && a[3][h]!=3) ok=false;
                            if (a[3][h]==3 && a[4][h]!=3) ok=false;
                            if (a[0][h]==3 && a[4][h]!=4) ok=false;
                            if (a[4][h]==4 && a[0][h]!=3) ok=false;
                        }
                        for (int h = 0; h < 5; ++h) {
                            if (a[1][h]==1) { if (h==0 || a[1][h-1]!=2) ok=false; }
                            if (a[1][h]==2) { if (h==4 || a[1][h+1]!=1) ok=false; }
                        }
                        if (a[3][2]!=2) ok=false;
                        if (a[0][0]!=4) ok=false;
                        for (int h = 0; h < 5; ++h) {
                            if (a[4][h]==1) { bool f=false; for(int nn=h-1;nn<=h+1;++nn) if(nn>=0&&nn<5&&a[2][nn]==2) f=true; if(!f) ok=false; }
                            if (a[2][h]==2) { bool f=false; for(int nn=h-1;nn<=h+1;++nn) if(nn>=0&&nn<5&&a[4][nn]==1) f=true; if(!f) ok=false; }
                        }
                        for (int h = 0; h < 5; ++h) {
                            if (a[4][h]==2) { bool f=false; for(int nn=h-1;nn<=h+1;++nn) if(nn>=0&&nn<5&&a[2][nn]==3) f=true; if(!f) ok=false; }
